We denote by $S_n$ the function from $\mathbb{R}^n \setminus \{0\}$ to $\mathbb{R}$ defined by
	\begin{equation*}
	S_n(x) \equiv 
	\begin{cases}
	\frac{1}{s_n} \log |x| & \forall x \in \mathbb{R}^n \setminus \{0\} \qquad \mbox{if } n=2 \\
	\frac{1}{(2-n) s_n} |x|^{2-n} & \forall x \in \mathbb{R}^n \setminus \{0\} \qquad \mbox{if } n>2
	\end{cases}
	\end{equation*}
	where $s_n$ denotes the $(n-1)$-dimensional measure of $\partial B_n(0,1)$.

We denote by $v_{\Omega}[\mu]$ the single layer potential with density $\mu$, {i.e.} the function defined by
	\begin{equation*}
	v_{\Omega}[\mu](x) \equiv \int_{\partial \Omega}{S_n(x-y) \mu(y) \,d\sigma_y} \qquad \forall x \in \mathbb{R}^n \, , \forall \mu \in L^2(\partial\Omega)\, .
	\end{equation*}

\label{sdp}
	The following statements hold.
	\begin{enumerate}
		\item[(i)] For all $\mu \in L^2(\partial\Omega)$, the function $v_{\Omega}[\mu]$ is harmonic in $\mathbb{R}^n\setminus \partial\Omega$. If $n\geq3$ or if $n=2$ and $\int_{\partial \Omega}\mu\, d\sigma=0$ then $v_{\Omega}[\mu]$ is also harmonic at infinity.

		\item[(ii)] If $\mu \in C^{0,\alpha}(\partial\Omega)$, then $v^+_{\Omega}[\mu] \in C^{1,\alpha}(\overline{\Omega})$ and the map from $C^{0,\alpha}(\partial\Omega)$ to $C^{1,\alpha}(\overline{\Omega})$  that  takes $\mu$ to $v^+_{\Omega}[\mu]$ is linear and continuous. Moreover, $v^-_{\Omega}[\mu] \in C^{1,\alpha}_{\mathrm{loc}}(\mathbb{R}^n \setminus \Omega)$ and the map from $C^{0,\alpha}(\partial \Omega)$ to $C^{1,\alpha}_{\mathrm{loc}}(\mathbb{R}^n \setminus \Omega)$  that  takes $\mu$ to $v^-_{\Omega}[\mu]$ is linear and continuous.

		\item[(iii)] If $\mu \in C^{0,\alpha}(\partial\Omega)$, then we have following jump relations
		\begin{equation*}
		\nu_\Omega(x) \cdot \nabla v^\pm_{\Omega}[\mu] (x) = \left( \mp \frac{1}{2} I + W^\ast_{\partial\Omega} \right)[\mu](x) \qquad \forall x \in \partial \Omega.
		\end{equation*}	

		\item[(iv)] The map from $C^{0,\alpha}(\partial\Omega)_0 \times \mathbb{R}$ to $C^{0,\alpha}(\partial\Omega)$  that  takes a pair $(\mu,\rho)$ to $V_{\partial\Omega}[\mu] + \rho$ is an isomorphism.
	\end{enumerate}

\label{kerneldef}
	Let $K$ be a measurable function from $\partial\Omega \times \partial\Omega$ to $\mathbb{R}$ and let $0 \leq \beta < n-1$. We say that $K$ is a continuous kernel of order $\beta$ if
	\begin{equation*}
	K(x,y) = k(x,y) |x-y|^{-\beta} \quad \forall(x,y)\in \partial\Omega \times \partial\Omega,
	\end{equation*}
	for some continuous function $k$ on $\partial\Omega \times \partial\Omega$.
	\\
	If $K$ is a continuous kernel of order $\beta$, we denote by  $\mathcal{K}_K$ the integral operator from $L^2(\partial\Omega)$ to itself defined by
	\begin{equation*}
	\mathcal{K}_K [\mu] (x) \equiv \int_{\partial\Omega} K(x,y) \mu (y) \,d\sigma_y \qquad \text{for a.e. } x \in \partial \Omega\, , \forall \mu \in L^2(\partial\Omega)\, .
	\end{equation*}

\label{rapprharm}
	Let $\Omega$ be an open bounded connected subset of $\mathbb{R}^n$ of class $C^{1,\alpha}$, such that $\mathbb{R}^n\setminus \overline{\Omega}$ is connected and $\overline{\Omega}\subset \Omega^o$. Then the map from $C^{0,\alpha}(\partial\Omega^o)_0 \times C^{0,\alpha}(\partial\Omega) \times C^{0,\alpha}(\partial\Omega)_0 \times \mathbb{R}^2$
	to $C^{1,\alpha}_{\mathrm{h}}(\overline{\Omega^o} \setminus \Omega) \times C^{1,\alpha}_{\mathrm{h}}(\overline{\Omega})$   that  takes a quintuple $(\mu^o,\mu^i,\eta^i,\rho^o,\rho^i)$ to the pair of functions $(U^o_\Omega[\mu^o,\mu^i,\eta^i,\rho^o,\rho^i], U^i_\Omega[\mu^o,\mu^i,\eta^i,\rho^o,\rho^i])$ defined by
	\begin{equation}\label{U^o,U^i}
	\begin{aligned}
	& U^o_\Omega[\mu^o,\mu^i,\eta^i,\rho^o,\rho^i] \equiv (v^+_{\Omega^o} [\mu^o] + v^-_{\Omega}[\mu^i] + \rho^o)_{| \overline{\Omega^o} \setminus \Omega}
	\\
	& U^i_\Omega[\mu^o,\mu^i,\eta^i,\rho^o,\rho^i] \equiv v^+_{\Omega}[\eta^i] + \rho^i
	\end{aligned}
	\end{equation}
	is bijective.

\ 
	The map is well defined. Indeed, by the harmonicity and regularity properties of single layer potentials (cf.~Theorem \ref{sdp} (i)-(ii)), we know that
	\begin{align*}
	&\Delta U^o_\Omega[\mu^o,\mu^i,\eta^i,\rho^o,\rho^i]=0 \quad \text{on } \Omega^o \setminus \overline{\Omega},
	\\
	&\Delta U^i_\Omega[\mu^o,\mu^i,\eta^i,\rho^o,\rho^i]=0 \quad \text{on } \Omega,
	\\
	&(U^o_\Omega[\mu^o,\mu^i,\eta^i,\rho^o,\rho^i],U^i_\Omega[\mu^o,\mu^i,\eta^i,\rho^o,\rho^i]) \in C^{1,\alpha}(\overline{\Omega^o} \setminus \Omega) \times C^{1,\alpha}(\overline{\Omega}),
	\end{align*}
	for all $(\mu^o,\mu^i,\eta^i,\rho^o,\rho^i) \in C^{0,\alpha}(\partial\Omega^o)_0 \times C^{0,\alpha}(\partial\Omega) \times C^{0,\alpha}(\partial\Omega)_0 \times \mathbb{R}^2$. We now show that it is bijective. So, we take a pair of functions $(h^o,h^i) \in C^{1,\alpha}_{\mathrm{h}}(\overline{\Omega^o} \setminus \Omega) \times C^{1,\alpha}_{\mathrm{h}}(\overline{\Omega})$ and we prove that there exists a unique quintuple $(\mu^o,\mu^i,\eta^i,\rho^o,\rho^i) \in C^{0,\alpha}(\partial\Omega^o)_0 \times C^{0,\alpha}(\partial\Omega) \times C^{0,\alpha}(\partial\Omega)_0 \times \mathbb{R}^2$ such that 
	\begin{equation}\label{h^o,h^i}
	(U^o_\Omega[\mu^o,\mu^i,\eta^i,\rho^o,\rho^i],U^i_\Omega[\mu^o,\mu^i,\eta^i,\rho^o,\rho^i])=(h^o,h^i).
	\end{equation}
	By the uniqueness of the classical solution of the Dirichlet boundary value problem, the second equation in \eqref{h^o,h^i} is equivalent to
	\begin{equation}\label{h^i}
	V_{\partial\Omega}[\eta^i] + \rho^i = h^i_{| \partial \Omega}
	\end{equation}
	(notice that, since $h^i$ is an element of $C^{1,\alpha}_{\mathrm{h}}(\overline{\Omega})$, we have $h^i_{|\partial\Omega} \in C^{1,\alpha} (\partial\Omega) \subseteq C^{0,\alpha} (\partial\Omega)$).
	By Theorem \ref{sdp} (iv), there exists a unique pair $(\eta^i,\rho^i) \in C^{0,\alpha}(\partial\Omega)_0 \times \mathbb{R}$ such that \eqref{h^i} holds.
	Then it remains to show that there exists a unique triple $(\mu^o,\mu^i,\rho^o) \in C^{0,\alpha}(\partial\Omega^o)_0 \times C^{0,\alpha}(\partial\Omega) \times \mathbb{R}$ such that 
	\begin{equation}\label{h^o}
		(v^+_{\Omega^o} [\mu^o] + v^-_{\Omega^i}[\mu^i] + \rho^o)_{| \overline{\Omega^o} \setminus \Omega} = h^o.
	\end{equation}
	By the jump relations for the single layer potential (cf.~Theorem \ref{sdp} (iii)) and by the uniqueness of the classical solution of the Neumann-Dirichlet mixed boundary value problem,                                               
	 equation \eqref{h^o} is equivalent to the following system of integral equations:
	\begin{equation}\label{sysinteq h^o}
	\begin{aligned}
	& V_{\partial\Omega^o} [\mu^o] + v^-_{\Omega}[\mu^i]_{|\partial\Omega^o} + \rho^o = h^o_{|\partial\Omega^o},
	\\
	& \left( \frac{1}{2} I + W^\ast_{\partial\Omega} \right) [\mu^i] + \nu_{\Omega} \cdot \nabla v^+_{\Omega^o}[\mu^o]_{|\partial\Omega} = \nu_{\Omega} \cdot \nabla h^o_{|\partial\Omega}
	\end{aligned}
	\end{equation}
	(notice that, by $h^o \in C^{1,\alpha}_{\mathrm{h}}(\overline{\Omega})$, we get $h^o_{|\partial\Omega} \in C^{1,\alpha} (\partial\Omega) \subseteq C^{0,\alpha} (\partial\Omega)$ and $\nu_{\Omega} \cdot \nabla h^o_{|\partial\Omega} \in C^{0,\alpha} (\partial\Omega)$).
	Then we observe that by Theorem \ref{sdp} (iv), the map from $C^{0,\alpha}(\partial\Omega^o)_0 \times C^{0,\alpha}(\partial\Omega) \times \mathbb{R}$ to $C^{0,\alpha}(\partial\Omega^o) \times C^{0,\alpha}(\partial\Omega)$  that  takes a triple $(\mu^o,\mu^i,\rho^o)$ to the pair of functions 
	 $\left(V_{\partial\Omega^o} [\mu^o] + \rho^o, \frac{1}{2} \mu^i \right)$	is an isomorphism. Moreover, by the properties of integral operators with real analytic kernel and no singularities (cf. Lanza de Cristoforis and Musolino \cite[Prop. 4.1]{LaMu13}) and by Theorem \ref{Schaudercompact}, the map from $C^{0,\alpha}(\partial\Omega^o)_0 \times C^{0,\alpha}(\partial\Omega) \times \mathbb{R}$ to $C^{0,\alpha}(\partial\Omega^o) \times C^{0,\alpha}(\partial\Omega)$  that  takes a triple $(\mu^o,\mu^i,\rho^o)$ to the pair of functions $(v^-_{\Omega}[\mu^i]_{|\partial\Omega^o},
	W^\ast_{\partial\Omega}[\mu^i] + \nu_{\Omega} \cdot \nabla v^+_{\Omega^o}[\mu^o]_{|\partial\Omega})$
	is compact. Hence, the map from $C^{0,\alpha}(\partial\Omega^o)_0 \times C^{0,\alpha}(\partial\Omega) \times \mathbb{R}$ to $C^{0,\alpha}(\partial\Omega^o) \times C^{0,\alpha}(\partial\Omega)$  that  takes a triple $(\mu^o,\mu^i,\rho^o)$ to the pair of functions
	\begin{equation*}
	\left(V_{\partial\Omega^o} [\mu^o] + v^-_{\Omega}[\mu^i]_{|\partial\Omega^o} + \rho^o, \left( \frac{1}{2} I + W^\ast_{\partial\Omega} \right) [\mu^i] + \nu_{\Omega} \cdot \nabla v^+_{\Omega^o}[\mu^o]_{|\partial\Omega} \right)
	\end{equation*}
	is a compact perturbation of an isomorphism and therefore it is a Fredholm operator of index 0. Thus, to complete the proof, it suffices to show that \eqref{sysinteq h^o} with $(h^o_{|\partial\Omega^o}, \nu_{\Omega} \cdot \nabla h^o_{|\partial\Omega}) = (0,0)$ implies $(\mu^o,\mu^i,\rho^o)=(0,0,0)$. If 
	\begin{equation}\label{sysinteq h^o=0}
	\left(V_{\partial\Omega^o} [\mu^o] + v^-_{\Omega}[\mu^i]_{|\partial\Omega^o} + \rho^o, \left( \frac{1}{2} I + W^\ast_{\partial\Omega} \right) [\mu^i] + \nu_{\Omega} \cdot \nabla v^+_{\Omega^o}[\mu^o]_{|\partial\Omega} \right) =(0,0),
	\end{equation}
	then by the jump relations for the single layer potential (cf.~Theorem \ref{sdp} (iii)) and by the uniqueness of the classical solution of Neumann-Dirichlet mixed boundary value problem, one deduces that $(v^+_{\Omega^o} [\mu^o] + v^-_{\Omega}[\mu^i] + \rho^o)_{| \overline{\Omega^o} \setminus \Omega}=0$. Moreover, by the continuity of $v_{\Omega}[\mu^i]$ in $\mathbb{R}^n$, we have that $(v^+_{\Omega^o} [\mu^o] + v^-_{\Omega}[\mu^i] + \rho^o)_{| \partial\Omega} = (v^+_{\Omega^o} [\mu^o] + v^+_{\Omega}[\mu^i] + \rho^o)_{|\partial\Omega} = 0$. Then by the uniqueness of the classical solution of Dirichlet boundary value problem in $\Omega$ we deduce that
	\begin{equation}\label{mu^o mu^i rho^o}
	(v^+_{\Omega^o} [\mu^o] + v^+_{\Omega}[\mu^i] + \rho^o)_{| \overline{\Omega} }=0.
	\end{equation} 
	By the jump relations for the single layer potential (cf.~Theorem \ref{sdp} (iii)), adding and subtracting the term $\nu_{\Omega} \cdot \nabla ( v^+_{\Omega^o}[\mu^o] +\rho^o)_{|\partial\Omega}$ and taking into account \eqref{mu^o mu^i rho^o}, we get 
	\begin{equation*}
	\begin{split}
	\mu^i &= \nu_{\Omega} \cdot \nabla v^-_{\Omega}[\mu^i]_{|\partial\Omega} - \nu_{\Omega} \cdot \nabla v^+_{\Omega}[\mu^i]_{|\partial\Omega}
	\\
	&= \nu_{\Omega} \cdot \nabla ( v^+_{\Omega^o}[\mu^o] + v^-_{\Omega}[\mu^i] +\rho^o)_{|\partial\Omega} -  \nu_{\Omega} \cdot \nabla ( v^+_{\Omega^o}[\mu^o] + v^+_{\Omega}[\mu^i] +\rho^o)_{|\partial\Omega} = 0.
	\end{split}
	\end{equation*}
	Thus, by \eqref{sysinteq h^o=0}, we obtain $V_{\Omega^o} [\mu^o] + \rho^o = 0$ on $\partial \Omega^o$, which implies $(\mu^o,\rho^o)=(0,0)$ (cf.~Theorem \ref{sdp} (iv)). Hence $(\mu^o,\mu^i,\rho^o)=(0,0,0)$ and the proof is complete.

\label{Alemma}
	Let $A$ be as in \eqref{Acondition}. Then the unique solution in $C^{1,\alpha}(\overline{\Omega^o} \setminus \Omega^i) \times C^{1,\alpha}(\overline{\Omega^i})$ of problem
	\begin{equation}\label{Aproblem}
	\begin{cases}
	\Delta u^o = 0 & \quad \mbox{in } \Omega^o \setminus \overline{\Omega^i}, 
	\\
	\Delta u^i = 0 & \quad \mbox{in } \Omega^i, 
	\\
	\nu_{\Omega^o}(x) \cdot \nabla u^o(x)= 0 & \quad\forall x \in \partial \Omega^o, 
	\\
	\nu_{\Omega^i}(x) \cdot \nabla u^o (x) - A_{11}(x) u^o(x) - A_{12}(x) u^i(x) = 0 & \quad\forall x \in \partial \Omega^i,
	\\
	\nu_{\Omega^i}(x) \cdot \nabla u^i (x) - A_{21}(x) u^o(x) - A_{22}(x) u^i(x) = 0 & \quad \forall x \in \partial \Omega^i,
	\end{cases}
	\end{equation}
	is $(u^o,u^i)=(0,0)$.

\label{J_A}
	Let $A$ be as in \eqref{Acondition}. Let $J_A$ be the map from $L^2(\partial\Omega^o)_0 \times L^2(\partial\Omega^i) \times L^2(\partial\Omega^i)_0 \times \mathbb{R}^2$ to $L^2(\partial\Omega^o) \times (L^2(\partial\Omega^i))^2$  that  takes a quintuple $(\mu^o,\mu^i,\eta^i,\rho^o,\rho^i)$ to the triple $J_A[\mu^o,\mu^i,\eta^i,\rho^o,\rho^i]$ defined by
	\begin{equation}\label{J_A eq}
	\begin{aligned}
	J_{A,1}[\mu^o,\mu^i,\eta^i,\rho^o,\rho^i] &\equiv \left( -\frac{1}{2} I + W^\ast_{\partial\Omega^o} \right) [\mu^o] + \nu_{\Omega^o} \cdot \nabla  v^-_{\Omega^i}[\mu^i]_{|\partial\Omega^o} \qquad \mbox{on } \partial\Omega^o,
	\\
	J_{A,2}[\mu^o,\mu^i,\eta^i,\rho^o,\rho^i] &\equiv \left( \frac{1}{2} I + W^\ast_{\partial\Omega^i} \right) [\mu^i] + \nu_{\Omega^i} \cdot \nabla  v^+_{\Omega^o}[\mu^o]_{|\partial\Omega^i} 
	\\
	 \quad - (A_{11},A_{12}) &\cdot (v^+_{\Omega^o}[\mu^o]_{|\partial\Omega^i} + V_{\partial\Omega^i}[\mu^i] + \rho^o ,V_{\partial\Omega^i}[\eta^i] + \rho^i  ) \qquad\mbox{on } \partial\Omega^i,
	\\
	J_{A,3}[\mu^o,\mu^i,\eta^i,\rho^o,\rho^i] &\equiv \left( -\frac{1}{2} I + W^\ast_{\partial\Omega^i} \right) [\eta^i] 
	\\
 \quad - (A_{21},A_{22}) &\cdot (v^+_{\Omega^o}[\mu^o]_{|\partial\Omega^i} + V_{\partial\Omega^i}[\mu^i] + \rho^o ,V_{\partial\Omega^i}[\eta^i] + \rho^i  )  \qquad \mbox{on } \partial\Omega^i.
	\end{aligned}
	\end{equation}
	Then the following statements hold.
	\begin{enumerate}
		\item[(i)] $J_A$ is a linear isomorphism from $L^2(\partial\Omega^o)_0 \times L^2(\partial\Omega^i) \times L^2(\partial\Omega^i)_0 \times \mathbb{R}^2$ to $L^2(\partial\Omega^o) \times (L^2(\partial\Omega^i))^2$.

		\item[(ii)] $J_A$ is a linear isomorphism from $C^0(\partial\Omega^o)_0 \times C^0(\partial\Omega^i) \times C^0(\partial\Omega^i)_0 \times \mathbb{R}^2$ to $C^0(\partial\Omega^o) \times (C^0(\partial\Omega^i))^2$.

		\item[(iii)] $J_A$ is a linear isomorphism from $C^{0,\alpha}(\partial\Omega^o)_0 \times C^{0,\alpha}(\partial\Omega^i) \times C^{0,\alpha}(\partial\Omega^i)_0 \times \mathbb{R}^2$ to $C^{0,\alpha}(\partial\Omega^o) \times (C^{0,\alpha}(\partial\Omega^i))^2$.
	\end{enumerate}

\label{propintsys}
	Let $A$ be as in \eqref{Acondition}. Let $(\mu^o,\mu^i,\eta^i,\rho^o,\rho^i) \in C^{0,\alpha}(\partial\Omega^o)_0 \times C^{0,\alpha}(\partial\Omega^i) \times C^{0,\alpha}(\partial\Omega^i)_0 \times \mathbb{R}^2$. Let $(U^o_{\Omega^i}[\cdot,\cdot,\cdot,\cdot,\cdot],U^i_{\Omega^i}[\cdot,\cdot,\cdot,\cdot,\cdot])$ be defined by \eqref{U^o,U^i}. Let $J_A$ be as in Proposition \ref{J_A}.
	Then $(U^o_{\Omega^i}[\mu^o,\mu^i,\eta^i,\rho^o,\rho^i],U^i_{\Omega^i}[\mu^o,\mu^i,\eta^i,\rho^o,\rho^i])$  is a solution of  \eqref{princeq} if and only if 
	\begin{equation}\label{princintsys}
	\begin{aligned}
	\begin{pmatrix}
	\mu^o
	\\
	\mu^i
	\\
	\eta^i
	\\
	\rho^o
	\\ 
	\rho^i
	\end{pmatrix}
	= J_A^{(-1)}&
	\left[
	\begin{pmatrix}
	f^o
	\\
	\mathcal{N}_{F_1}(v^+_{\Omega^o}[\mu^o]_{|\partial\Omega^i} + V_{\partial\Omega^i}[\mu^i] +\rho^o ,V_{\partial\Omega^i}[\eta^i] +\rho^i)
	\\
	\mathcal{N}_{F_2}(v^+_{\Omega^o}[\mu^o]_{|\partial\Omega^i} + V_{\partial\Omega^i}[\mu^i] +\rho^o ,V_{\partial\Omega^i}[\eta^i] +\rho^i)
	\end{pmatrix}
	\right. 
	\\
	& \left.
	- \begin{pmatrix}
	0 & 0 & 0 \\
	0 & A_{11} & A_{12} \\
	0 & A_{21} & A_{22} 
	\end{pmatrix} 
	\begin{pmatrix}
	0
	\\
	v^+_{\Omega^o}[\mu^o]_{|\partial\Omega^i} + V_{\partial\Omega^i}[\mu^i] +\rho^o
	\\
	V_{\partial\Omega^i}[\eta^i] +\rho^i
	\end{pmatrix} \right].
	\end{aligned}
	\end{equation}

\ 
	By Lemma \ref{rapprharm} and by the jump relations of Theorem \ref{sdp}, we know that if $(\mu^o,\mu^i,\eta^i,\rho^o,\rho^i) \in C^{0,\alpha}(\partial\Omega^o)_0 \times C^{0,\alpha}(\partial\Omega^i) \times C^{0,\alpha}(\partial\Omega^i)_0 \times \mathbb{R}^2$ then the pair \[(U^o_{\Omega^i}[\mu^o,\mu^i,\eta^i,\rho^o,\rho^i],U^i_{\Omega^i}[\mu^o,\mu^i,\eta^i,\rho^o,\rho^i])\]
	defined by \eqref{U^o,U^i} is a solution of problem \eqref{princeq} if an only if
	\begin{equation}\label{intsys}
	\begin{split}
	& \begin{pmatrix}
	\left( -\frac{1}{2} I + W^\ast_{\partial\Omega^o} \right) [\mu^o] + \nu_{\Omega^o} \cdot \nabla  v^-_{\Omega^i}[\mu^i]_{|\partial\Omega^o}
	\\
	\left( \frac{1}{2} I + W^\ast_{\partial\Omega^i} \right) [\mu^i] + \nu_{\Omega^i} \cdot \nabla  v^+_{\Omega^o}[\mu^o]_{|\partial\Omega^i} 
	\\
	\left( -\frac{1}{2} I + W^\ast_{\partial\Omega^i} \right) [\eta^i] 
	\end{pmatrix}
	\\ &\qquad =
	\begin{pmatrix}
	f^o
	\\
	\mathcal{N}_{F_1}(v^+_{\Omega^o}[\mu^o]_{|\partial\Omega^i} + V_{\partial\Omega^i}[\mu^i] +\rho^o ,V_{\partial\Omega^i}[\eta^i] +\rho^i)
	\\
	\mathcal{N}_{F_2}(v^+_{\Omega^o}[\mu^o]_{|\partial\Omega^i} + V_{\partial\Omega^i}[\mu^i] +\rho^o ,V_{\partial\Omega^i}[\eta^i] +\rho^i)
	\end{pmatrix}.
	\end{split}
	\end{equation}

	Then, by subtracting in both sides of \eqref{intsys} the term
	\begin{equation*}
	\begin{pmatrix}
	0 & 0 & 0 \\
	0 & A_{11} & A_{12} \\
	0 & A_{21} & A_{22} 
	\end{pmatrix} 
	\begin{pmatrix}
	0
	\\
	v^+_{\Omega^o}[\mu^o]_{|\partial\Omega^i} + V_{\partial\Omega^i}[\mu^i] +\rho^o
	\\
	V_{\partial\Omega^i}[\eta^i] +\rho^i
	\end{pmatrix}
	\in C^{0,\alpha}(\partial\Omega^o) \times (C^{0,\alpha}(\partial\Omega^i))^2
	\end{equation*} 
	and by the invertibility of $J_A$ from $C^{0,\alpha}(\partial\Omega^o)_0 \times C^{0,\alpha}(\partial\Omega^i) \times C^{0,\alpha}(\partial\Omega^i)_0 \times \mathbb{R}^2$ to $C^{0,\alpha}(\partial\Omega^o) \times (C^{0,\alpha}(\partial\Omega^i))^2$ provided by Proposition \ref{J_A} (iii), the validity of the statement follows.

\ 
	By the properties of integral operators with real analytic kernel and no singularities (cf. Lanza de Cristoforis and Musolino \cite[Prop. 4.1]{LaMu13}) and by the compactness of the embedding of $C^{0,\alpha}(\partial\Omega^i)$ into $C^0(\partial\Omega^i)$, $v^+_{\Omega^o}[\cdot]_{|\partial\Omega^i}$ is compact from $C^0(\partial\Omega^o)_0$ into $C^0(\partial\Omega^i)$. By mapping properties of the single layer potential (cf.~Miranda \cite[Chap.~II, \S14, III]{Mi70}) and by the compactness of the embedding of $C^{0,\alpha}(\partial\Omega^i)$ into $C^0(\partial\Omega^i)$, $V_{\partial\Omega^i}$ is compact from $C^0(\partial\Omega^i)$ into itself. Hence, by the bilinearity and continuity of the product of continuous functions, the map from $C^0(\partial\Omega^o)_0 \times C^0(\partial\Omega^i) \times C^0(\partial\Omega^i)_0 \times \mathbb{R}^2$ to $C^0(\partial\Omega^o) \times (C^0(\partial\Omega^i))^2$  that  takes the quintuple $(\mu^o,\mu^i,\eta^i,\rho^o,\rho^i)$ to the triple given by
	\begin{equation*}
	\begin{pmatrix}
	0 & 0 & 0 \\
	0 & A_{11} & A_{12} \\
	0 & A_{21} & A_{22} 
	\end{pmatrix} 
	\begin{pmatrix}
	0
	\\
	v^+_{\Omega^o}[\mu^o]_{|\partial\Omega^i} + V_{\partial\Omega^i}[\mu^i] +\rho^o
	\\
	V_{\partial\Omega^i}[\eta^i] +\rho^i
	\end{pmatrix}
	\end{equation*} 
	is continuous and maps bounded sets into sets with compact closure, {i.e.}, is compact. Moreover, by assumption \eqref{introfunconditions}, one readily verifies that the operators $\mathcal{N}_{F_1}$ and $\mathcal{N}_{F_2}$ are continuous from $(C^0(\partial\Omega^i))^2$ into $C^0(\partial\Omega^i)$.  Hence the map from $C^0(\partial\Omega^o)_0 \times C^0(\partial\Omega^i) \times C^0(\partial\Omega^i)_0$ to $C^0(\partial\Omega^o) \times (C^0(\partial\Omega^i))^2$  that  takes the quintuple $(\mu^o,\mu^i,\eta^i,\rho^o,\rho^i)$ to the triple 
	\begin{equation*}
	\begin{pmatrix}
	f^0
	\\
	\mathcal{N}_{F_1}(v^+_{\Omega^o}[\mu^o]_{|\partial\Omega^i} + V_{\partial\Omega^i}[\mu^i] +\rho^o ,V_{\partial\Omega^i}[\eta^i] +\rho^i)
	\\
	\mathcal{N}_{F_2}(v^+_{\Omega^o}[\mu^o]_{|\partial\Omega^i} + V_{\partial\Omega^i}[\mu^i] +\rho^o ,V_{\partial\Omega^i}[\eta^i] +\rho^i)
	\end{pmatrix}
	\end{equation*}
	is compact. Finally, by Proposition \ref{J_A} (ii),  $J_A$ is a linear isomorphism from $C^0(\partial\Omega^o)_0 \times C^0(\partial\Omega^i) \times C^0(\partial\Omega^i)_0 \times \mathbb{R}^2$ to $C^0(\partial\Omega^o) \times (C^0(\partial\Omega^i))^2$ and, accordingly, $T_A$ is compact.

\ 
	We plan to apply the Leray-Schauder Theorem \ref{Thm Leray Schauder} to the operator $T_A$ defined by \eqref{T} in the Banach space $C^0(\partial\Omega^o)_0 \times C^0(\partial\Omega^i) \times C^0(\partial\Omega^i)_0 \times \mathbb{R}^2$. By Proposition \ref{Tcontcomp} we already know that $T_A$ is a continuous operator from $C^0(\partial\Omega^o)_0 \times C^0(\partial\Omega^i) \times C^0(\partial\Omega^i)_0 \times \mathbb{R}^2$ to $C^0(\partial\Omega^o) \times (C^0(\partial\Omega^i))^2$ and maps bounded sets into sets with compact closure. So in order to apply the Leray-Schauder Theorem \ref{Thm Leray Schauder}, we are left to show that if $\lambda \in ]0,1[$ and if
	\begin{equation}\label{mu=lamdaT(mu)}
	(\mu^o,\mu^i,\eta^i,\rho^o,\rho^i) = \lambda T_A(\mu^o,\mu^i,\eta^i,\rho^o,\rho^i)
	\end{equation}
	with $(\mu^o,\mu^i,\eta^i,\rho^o,\rho^i) \in C^0(\partial\Omega^o)_0 \times C^0(\partial\Omega^i) \times C^0(\partial\Omega^i)_0 \times \mathbb{R}^2$,  then there exists a constant $C \in ]0,+\infty[$ (which does not depend on $\lambda$ and $(\mu^o,\mu^i,\eta^i,\rho^o,\rho^i)$), such that
	\begin{equation}\label{mu<C}
	\|(\mu^o,\mu^i,\eta^i,\rho^o,\rho^i)\|_{C^0(\partial\Omega^o) \times (C^0(\partial\Omega^i))^2\times \mathbb{R}^2} \leq C.
	\end{equation}
	By \eqref{mu=lamdaT(mu)} and by $|\lambda|<1$, we readily deduce that
	\begin{equation}\label{|mu|<|T(mu)|}
	\begin{split}
	&\|(\mu^o,\mu^i,\eta^i,\rho^o,\rho^i)\|_{C^0(\partial\Omega^o) \times (C^0(\partial\Omega^i))^2 \times \mathbb{R}^2} \\ &\qquad\leq \|T_A(\mu^o,\mu^i,\eta^i,\rho^o,\rho^i)\|_{C^0(\partial\Omega^o) \times (C^0(\partial\Omega^i))^2}\, .
	\end{split}
	\end{equation}	By the growth condition \eqref{conditionF1F2}, we can show that 
	\begin{equation}\label{inequalityNF1NF2}
	\begin{split}
	&\left\| \begin{pmatrix}
	\mathcal{N}_{F_1}(h^i_1,h^i_2)
	\\
	\mathcal{N}_{F_2}(h^i_1,h^i_2)
	\end{pmatrix} - A \begin{pmatrix}
	h^i_1 \\ h^i_2
	\end{pmatrix} \right\|_{(C^0(\partial\Omega^i))^2} \\
	& \qquad\leq C_F (1+\|h^i_1\|_{C^0(\partial\Omega^i)}+\|h^i_2\|_{C^0(\partial\Omega^i)})^\delta
	\end{split}
	\end{equation}
	for all pair of functions $(h^i_1,h^i_2) \in (C^0(\partial\Omega^i))^2$. Hence, by \eqref{|mu|<|T(mu)|} and by the definition of $T_A$ in \eqref{T}, we deduce that there exist two constants $C_1,C_2 \in ]0,+\infty[$, which depend only on the operator norm of $J_A^{(-1)}$ from $C^0(\partial\Omega^o) \times (C^0(\partial\Omega^i))^2$ to $C^0(\partial\Omega^o)_0 \times C^0(\partial\Omega^i) \times C^0(\partial\Omega^i)_0 \times \mathbb{R}^2$ (cf.~Theorem \ref{J_A} (ii)), on $\|f^o\|_{\partial\Omega^o}$, on the constant $C_F \in ]0,+\infty[$ provided by the growth
	condition \eqref{conditionF1F2} (cf. \eqref{inequalityNF1NF2}), on the norm of the bounded linear operator $v^+_{\Omega^o}[\cdot]_{|\partial\Omega^i}$ from $C^0(\partial\Omega^o)$ to $C^0(\partial\Omega^i)$, and on the norm of the bounded linear operator $V_{\partial\Omega^i}$ from $C^0(\partial\Omega^i)$ into itself, such that
	\[
	\begin{split}
	&\|(\mu^o,\mu^i,\eta^i,\rho^o,\rho^i)\|_{C^0(\partial\Omega^o) \times (C^0(\partial\Omega^i))^2 \times \mathbb{R}^2}\\ & \qquad \leq 
	C_1 (C_2 + \|(\mu^o,\mu^i,\eta^i,\rho^o,\rho^i)\|_{C^0(\partial\Omega^o) \times (C^0(\partial\Omega^i))^2 \times \mathbb{R}^2} )^\delta\, .
	\end{split}
	\]
	Then, by a straightforward calculation, we can show the existence of a constant $C>0$ such that inequality \eqref{mu<C} holds true (cf. Lanza de Cristoforis \cite[proof of Thm.~7.2]{La07}).	Hence, by the  Leray-Schauder Theorem \ref{Thm Leray Schauder} there exists at least one solution \[(\mu^o_0,\mu^i_0,\eta^i_0,\rho^o_0,\rho^i_0) \in C^0(\partial\Omega^o)_0 \times C^0(\partial\Omega^i) \times C^0(\partial\Omega^i)_0 \times \mathbb{R}^2\] of  $(\mu^o,\mu^i,\eta^i,\rho^o,\rho^i) = T_A(\mu^o,\mu^i,\eta^i,\rho^o,\rho^i)$.	Finally, by the definition of $T_A$ (cf. \eqref{T}), we conclude that $(\mu^o_0,\mu^i_0,\eta^i_0,\rho^o_0,\rho^i_0)$ is a solution in $C^0(\partial\Omega^o)_0 \times C^0(\partial\Omega^i) \times C^0(\partial\Omega^i)_0 \times \mathbb{R}^2$ of the nonlinear system \eqref{princintsys}.

\label{prop u^o_0,u^i_0}
	Let A be as in \eqref{Acondition}. Let assumptions \eqref{conditionF1F2} and \eqref{conditionNF} hold. Then the nonlinear system \eqref{princintsys} has at least one solution $(\mu^o_0,\mu^i_0,\eta^i_0,\rho^o_0,\rho^i_0) \in C^{0,\alpha}(\partial\Omega^o)_0 \times C^{0,\alpha}(\partial\Omega^i) \times C^{0,\alpha}(\partial\Omega^i)_0 \times \mathbb{R}^2$. In particular, problem \eqref{princeq} has at least one solution $(u^o_0,u^i_0) \in C^{1,\alpha}(\overline{\Omega^o} \setminus \Omega^i) \times C^{1,\alpha}(\overline{\Omega^i})$ given by
	\begin{equation}\label{u^o_0,u^i_0}
	(u^o_0,u^i_0) \equiv  (U^o_{\Omega^i}[\mu^o_0,\mu^i_0,\eta^i_0,\rho^o_0,\rho^i_0],U^i_{\Omega^i}[\mu^o_0,\mu^i_0,\eta^i_0,\rho^o_0,\rho^i_0])
	\end{equation}
	where the pair $(U^o_{\Omega^i}[\cdot,\cdot,\cdot,\cdot,\cdot],U^i_{\Omega^i}[\cdot,\cdot,\cdot,\cdot,\cdot])$ is defined by \eqref{U^o,U^i}.

\ 
	Let $T_A$ be as in \eqref{T}. By Proposition \ref{prop mu_0},  we deduce the existence of a quintuple $(\mu^o_0,\mu^i_0,\eta^i_0,\rho^o_0,\rho^i_0) \in C^0(\partial\Omega^o)_0 \times C^0(\partial\Omega^i) \times C^0(\partial\Omega^i)_0 \times \mathbb{R}^2$ such that $
	(\mu^o_0,\mu^i_0,\eta^i_0,\rho^o_0,\rho^i_0) = T_A(\mu^o_0,\mu^i_0,\eta^i_0,\rho^o_0,\rho^i_0).
$ By the mapping properties of integral operators with real analytic kernel and no singularities (cf. Lanza de Cristoforis and Musolino \cite[Prop. 4.1]{LaMu13}), $v^+_{\Omega^o}[\mu^o_0]_{|\partial\Omega^i}$ belongs to $C^{0,\alpha}(\partial\Omega^i)$. By classical results in potential theory (cf.~Miranda \cite[Chap.~II, \S14, III]{Mi70}), $V_{\Omega^i}[\mu^i_0]$ and $V_{\Omega^i}[\eta^i_0]$ belong to $C^{0,\alpha}(\partial\Omega^i)$. Then, by condition \eqref{conditionNF} and by the membership of $A \in M_2(C^{0,\alpha} (\partial\Omega^i))$ and of $f^o \in C^{0,\alpha} (\partial\Omega^o)$, we obtain that
	\begin{equation*}
	\begin{split}
	&\begin{pmatrix}
	f^o
	\\
	\mathcal{N}_{F_1}(v^+_{\Omega^o}[\mu^o_0]_{|\partial\Omega^i} + V_{\partial\Omega^i}[\mu^i_0] +\rho^o_0 ,V_{\partial\Omega^i}[\eta^i_0] +\rho^i_0)
	\\
	\mathcal{N}_{F_2}(v^+_{\Omega^o}[\mu^o_0]_{|\partial\Omega^i} + V_{\partial\Omega^i}[\mu^i_0] +\rho^o_0 ,V_{\partial\Omega^i}[\eta^i_0] +\rho^i_0)
	\end{pmatrix}
	\\ &\qquad - \begin{pmatrix}
	0 & 0 & 0 \\
	0 & A_{11} & A_{12} \\
	0 & A_{21} & A_{22} 
	\end{pmatrix} 
	\begin{pmatrix}
	0
	\\
	v^+_{\Omega^o}[\mu^o_0]_{|\partial\Omega^i} + V_{\partial\Omega^i}[\mu^i_0] +\rho^o_0
	\\
	V_{\partial\Omega^i}[\eta^i_0] +\rho^i_0
	\end{pmatrix}
	\end{split}
	\end{equation*}
	belongs to the product space $C^{0,\alpha}(\partial\Omega^o) \times (C^{0,\alpha}(\partial\Omega^i))^2$. Finally, by the invertibility of the operator $J_A$ from $C^{0,\alpha}(\partial\Omega^o)_0 \times C^{0,\alpha}(\partial\Omega^i) \times C^{0,\alpha}(\partial\Omega^i)_0 \times \mathbb{R}^2$ to $C^{0,\alpha}(\partial\Omega^o) \times (C^{0,\alpha}(\partial\Omega^i))^2$, we obtain that $(\mu^o_0,\mu^i_0,\eta^i_0,\rho^o_0,\rho^i_0) \in C^{0,\alpha}(\partial\Omega^o)_0 \times C^{0,\alpha}(\partial\Omega^i) \times C^{0,\alpha}(\partial\Omega^i)_0 \times \mathbb{R}^2$.	In particular, by Proposition \ref{propintsys} we deduce that the pair given by \eqref{u^o_0,u^i_0} is a solution of   \eqref{princeq} (cf.~\eqref{T}).

\label{M=0prop}
	Let A be as in \eqref{Acondition}. Let assumptions \eqref{conditionF1F2} and \eqref{conditionNF} hold. Let
	\begin{equation*}
	(\phi,\mu^o,\mu^i,\eta^i,\rho^o,\rho^i) \in \mathcal{A}^{\Omega^o}_{\partial\Omega^i} \times C^{0,\alpha}(\partial\Omega^o)_0 \times C^{0,\alpha}(\partial\Omega^i) \times C^{0,\alpha}(\partial\Omega^i)_0 \times \mathbb{R}^2.
	\end{equation*}
	Then the pair of functions
	\begin{equation*}
	(U^o_{\Omega^i[\phi]}[\mu^o,\mu^i\circ \phi^{(-1)},\eta^i\circ \phi^{(-1)},\rho^o,\rho^i],U^i_{\Omega^i[\phi]}[\mu^o,\mu^i\circ \phi^{(-1)},\eta^i\circ \phi^{(-1)},\rho^o,\rho^i])
	\end{equation*}
	defined by \eqref{U^o,U^i} is a solution of problem \eqref{princeqpertu} if and only if 
	\begin{equation}\label{M=0}
	M[\phi,\mu^o,\mu^i,\eta^i,\rho^o,\rho^i] = (0,0,0).
	\end{equation}
	In particular, equation
	\begin{equation}\label{M_0=0}
	M[\phi_0,\mu^o,\mu^i,\eta^i,\rho^o,\rho^i] = (0,0,0)
	\end{equation}
	is equivalent to the system \eqref{princintsys} and has a solution $(\mu^o_0,\mu^i_0,\eta^i_0,\rho^o_0,\rho^i_0) \in  C^{0,\alpha}(\partial\Omega^o)_0 \times C^{0,\alpha}(\partial\Omega^i) \times C^{0,\alpha}(\partial\Omega^i)_0 \times \mathbb{R}^2$  (recall that $\phi_0\equiv \text{id}_{\partial\Omega^i}$).

\ 
	We first observe that, by the regularity of $\phi \in \mathcal{A}^{\Omega^o}_{\partial\Omega^i}$, if $(\mu^o,\mu^i,\eta^i,\rho^o,\rho^i) \in  C^{0,\alpha}(\partial\Omega^o)_0 \times C^{0,\alpha}(\partial\Omega^i) \times C^{0,\alpha}(\partial\Omega^i)_0 \times \mathbb{R}^2$, then
	\begin{equation*}
	(\mu^o,\mu^i,\eta^i,\rho^o,\rho^i) \in C^{0,\alpha}(\partial\Omega^o)_0 \times C^{0,\alpha}(\partial\Omega^i) \times C^{0,\alpha}(\partial\Omega^i)_0 \times \mathbb{R}^2.
	\end{equation*}
	Moreover, since $\overline{\Omega^i[\phi]} \subset \Omega^o$, we can apply Lemma \ref{rapprharm} with $\Omega=\Omega^i[\phi]$. Then by the jump relations for the single layer potential (cf.~Theorem \ref{sdp} (iii)), by a change of variable on $\phi(\partial \Omega^i)$ and by the definition of $M$ (cf.~\eqref{M}), we obtain that the pair of functions
	\begin{align*}
	& U^o_{\Omega^i[\phi]}[\mu^o,\mu^i\circ \phi^{(-1)},\eta^i\circ \phi^{(-1)},\rho^o,\rho^i] = (v^+_{\Omega^o} [\mu^o] + v^-_{\Omega^i[\phi]}[\mu^i\circ \phi^{(-1)}] + \rho^o)_{| \overline{\Omega^o} \setminus \Omega^i[\phi]},
	\\
	& U^i_{\Omega^i[\phi]}[\mu^o,\mu^i\circ \phi^{(-1)},\eta^i\circ \phi^{(-1)},\rho^o,\rho^i] = v^+_{\Omega^i[\phi]}[\eta^i\circ \phi^{(-1)}] + \rho^i
	\end{align*}
	is a solution of problem \eqref{princeqpertu} if and only if \eqref{M=0} is satisfied.  Finally,  since $\phi_0\equiv \text{id}_{\partial\Omega^i}$ (cf. \eqref{phi0}) and by the definition of $J_A$ (cf.~\eqref{J_A eq}), we obtain that, for all $(\mu^o,\mu^i,\eta^i,\rho^o,\rho^i) \in  C^{0,\alpha}(\partial\Omega^o)_0 \times C^{0,\alpha}(\partial\Omega^i) \times C^{0,\alpha}(\partial\Omega^i)_0 \times \mathbb{R}^2$,
	equation \eqref{M_0=0} is equivalent to the system \eqref{princintsys}. Then the existence of a solution $(\mu^o_0,\mu^i_0,\eta^i_0,\rho^o_0,\rho^i_0)$ of \eqref{M_0=0} follows by Proposition \ref{prop mu_0}.

\label{diffMprop}
	Let assumptions \eqref{conditionF1F2} and \eqref{conditionNF*} hold. Let $(\mu^o_0,\mu^i_0,\eta^i_0,\rho^o_0,\rho^i_0) \in C^{0,\alpha}(\partial\Omega^o)_0 \times C^{0,\alpha}(\partial\Omega^i) \times C^{0,\alpha}(\partial\Omega^i)_0 \times \mathbb{R}^2$  be as in Proposition \ref{prop u^o_0,u^i_0}. Let $A_{\mathcal{N}_F,0}$ be as in \eqref{A_{N_F}}-\eqref{A_{N_F}bis} and assume that satisfies assumption \eqref{Acondition}. Then the partial differential of $M$ with respect to $(\mu^o,\mu^i,\eta^i,\rho^o,\rho^i)$ evaluated at the point $(\phi_0,\mu^o_0,\mu^i_0,\eta^i_0,\rho^o_0,\rho^i_0)$, which we denote by 
	\begin{equation}\label{partdiff M}
	\partial_{(\mu^o, \mu^i, \eta^i, \rho^o,\rho^i)} M[\phi_0,\mu^o_0, \mu^i_0 ,\eta^i_0,\rho^o_0,\rho^i_0],
	\end{equation}
	is an isomorphism from $C^{0,\alpha}(\partial\Omega^o)_0 \times C^{0,\alpha}(\partial\Omega^i) \times C^{0,\alpha}(\partial\Omega^i)_0 \times \mathbb{R}^2$ to $C^{0,\alpha}(\partial\Omega^o) \times (C^{0,\alpha}(\partial\Omega^i))^2$.

\label{u^o_phi,u^i_phi def}
	Let assumptions \eqref{conditionF1F2} and \eqref{conditionNF*} hold. Let $A_{\mathcal{N}_F,0}$ be as in \eqref{A_{N_F}}-\eqref{A_{N_F}bis} and assume that satisfies assumption \eqref{Acondition}. Let $Q_0$ and $\Lambda\equiv (M^o,M^i,N^i,R^o,R^i)$ be as in Theorem \ref{M^oteo}. Then, for each $\phi \in Q_0$ we set
	\begin{align*}
	 u^o_\phi(x)  &= U^o_{\Omega^i[\phi]}[M^o[\phi],M^i[\phi]\circ \phi^{(-1)},N^i[\phi]\circ \phi^{(-1)},R^o[\phi],R^i[\phi]](x)  \\& \quad\qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad\qquad  \forall x \in \overline{\Omega^o} \setminus  \Omega^i[\phi],
	\\
	u^i_\phi(x)  &= U^i_{\Omega^i[\phi]}[M^o[\phi],M^i[\phi]\circ \phi^{(-1)},N^i[\phi]\circ \phi^{(-1)},R^o[\phi],R^i[\phi]](x) \quad  \forall x \in \overline{\Omega^i[\phi]},
	\end{align*}
	where the pair $(U^o_{\Omega^i[\phi]}[\cdot,\cdot,\cdot,\cdot,\cdot],U^i_{\Omega^i[\phi]}[\cdot,\cdot,\cdot,\cdot,\cdot])$ is defined by \eqref{U^o,U^i}.

\label{upertuex}
	Let assumptions \eqref{conditionF1F2} and \eqref{conditionNF*} hold. Let $A_{\mathcal{N}_F,0}$ be as in \eqref{A_{N_F}}-\eqref{A_{N_F}bis} and assume that satisfies assumption \eqref{Acondition}. Let $Q_0$ be as in Theorem \ref{M^oteo} and let $(u^o_\phi,u^i_\phi)$ be as in Definition \ref{u^o_phi,u^i_phi def}. Then, for all $\phi \in Q_0$, $(u^o_\phi,u^i_\phi) \in C^{1,\alpha}(\overline{\Omega^o} \setminus \Omega^i[\phi]) \times C^{1,\alpha}(\overline{\Omega^i[\phi]})$
	is a solution of problem \eqref{princeqpertu}. In particular $(u^o_{\phi_0},u^i_{\phi_0})= (u^o_0,u^i_0)$	is a solution of problem \eqref{princeq}.

\label{upertuana}
	Let assumptions \eqref{conditionF1F2} and \eqref{conditionNF*} hold. Let $A_{\mathcal{N}_F,0}$ be as in \eqref{A_{N_F}}-\eqref{A_{N_F}bis} and assume that satisfies assumption \eqref{Acondition}. Let $Q_0$ be as in Theorem \ref{M^oteo} and let $(u^o_\phi,u^i_\phi)$ be as in Definition \ref{u^o_phi,u^i_phi def}. Then, the following statements hold.
	\begin{enumerate}
		\item[(i)] Let $\Omega_\mathtt{int}$ be a bounded open subset of $\Omega^o$. Let $Q_\mathtt{int} \subseteq Q_0$ be an open neighbourhood of $\phi_0$ such that  \[
		\overline{\Omega_\mathtt{int}} \subset {\Omega^i[\phi]} \quad \forall \phi \in Q_\mathtt{int}.
		\]
		Then the map from $Q_\mathtt{int}$ to $C^{1,\alpha}(\overline{\Omega_\mathtt{int}})$  that  takes $\phi$ to $u^i_{\phi| \overline{\Omega_\mathtt{int}}}$ is real analytic.

		\item[(ii)] Let $\Omega_\mathtt{ext}$ be a bounded open subset of $\Omega^o$. Let $Q_\mathtt{ext} \subseteq Q_0$ be an open neighbourhood of $\phi_0$ such that  \[
				\overline{\Omega_\mathtt{ext}} \subset \Omega^o \setminus \overline{\Omega^i[\phi]} \quad \forall \phi \in Q_\mathtt{ext}.\]	Then the map from $Q_\mathtt{ext}$ to $C^{1,\alpha}(\overline{\Omega_\mathtt{ext}})$  that  takes $\phi$ to $u^o_{\phi| \overline{\Omega_\mathtt{ext}}}$ is real analytic.
	\end{enumerate}

\ 
 We  prove (i).  By Definition \ref{u^o_phi,u^i_phi def}, by \eqref{U^o,U^i} and by Lemma \ref{lemmanotation}, we have
	\begin{equation*}
	\begin{split}
	u^i_\phi(x) &= U^i_{\Omega^i[\phi]}[M^o[\phi],M^i[\phi]\circ \phi^{(-1)},N^i[\phi]\circ \phi^{(-1)},R^o[\phi],R^i[\phi]](x) 




	\\
	& = \int_{\partial\Omega^i}  S_n(x-\phi(s))  \, N^i[\phi](s) \, \tilde{\sigma}_n[\phi](s) \,d\sigma_s	+ R^i[\phi]	\qquad \forall x \in \overline{\Omega^i[\phi]}
	\end{split}
	\end{equation*}
	and for all $\phi \in Q_0$. By the assumption $Q_\mathtt{int} \subseteq Q_0$ and Theorem \ref{M^oteo}, we know that the map from $Q_\mathtt{int}$ to $\mathbb{R}$  that  takes $\phi$ to $R^i[\phi]$ is real analytic. Moreover, by the real analyticity of $N^i[\cdot]$ (cf.~Theorem \ref{M^oteo}) and by the properties of integral operators with real analytic kernels and no singularities (see Lanza de Cristoforis and Musolino \cite[Prop. 4.1]{LaMu13}), we can prove that the map from $Q_\mathtt{int}$ to $C^{1,\alpha}(\overline{\Omega_\mathtt{int}})$  that  takes $\phi$ to the function $
	\int_{\partial\Omega^i}  S_n(x-\phi(s))  \, N^i[\phi](s) \, \tilde{\sigma}_n[\phi](s) \,d\sigma_s$ of the variable $x \in \overline{\Omega_\mathtt{int}}$
	is real analytic (see also Lemma \ref{lemmanotation}). Hence, we deduce the validity of (i).  The proof of (ii) is similar and it is left to the reader.
